        getChartData(state) {
            var startLabel = this._t('chart_start');
            var labels = state.domainState.squadCostsHistory.map(function(_, i) {
                return i === 0 ? startLabel : 'R' + i;
            });
            return {
                financialChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.squadCostsHistory },
                        { data: state.domainState.costLimitHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastState = window.mySimulation.state.domainState;

            var totalScore = lastState.financialScore + lastState.strategicScore + lastState.ethicsScore;
            var maxScore = 100;
            var pct = Math.round((totalScore / maxScore) * 100);

            var performance = this._t('perf_needs');
            if (pct >= 80) performance = this._t('perf_excellent');
            else if (pct >= 60) performance = this._t('perf_good');
            else if (pct >= 40) performance = this._t('perf_fair');

            var insights = [];
            if (lastState.gap <= 0) {
                insights.push(this._t('ins_gap_closed'));
            } else {
                insights.push(this._t('ins_gap_open').split('{gap}').join(lastState.gap.toFixed(1)));
            }
            if (lastState.ethicsScore >= 30) {
                insights.push(this._t('ins_ethics'));
            }
            if (lastState.sportingRisk >= 20) {
                insights.push(this._t('ins_sporting_risk'));
            }
            if (lastState.wageToRevenue <= 70) {
                insights.push(this._t('ins_wage_ratio'));
            }

            // display only: the end screen prints these numbers, so they are rounded to one decimal; the band above and the stored state keep the unrounded values
            var r1 = function(v) { var n = Number(v); return isFinite(n) ? Math.round(n * 10) / 10 : v; };
            return {
                totalScore: r1(totalScore),
                financialScore: r1(lastState.financialScore),
                strategicScore: r1(lastState.strategicScore),
                ethicsScore: r1(lastState.ethicsScore),
                performance: performance,
                gapRemaining: r1(lastState.gap),
                insights: insights
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            var period = state.currentPeriod;

            if (period === 1 && ds.gap > 15) {
                return window.mySimulation.t('hint_gap_large');
            }
            if (period === 1 && ds.fonsecaStatus === 'roster') {
                return window.mySimulation.t('hint_fonseca_kept');
            }
            if (period === 2 && ds.gap > 0) {
                return window.mySimulation.t('hint_gap_remains');
            }
            if (period === 2 && ds.sportingRisk >= 20) {
                return window.mySimulation.t('hint_sporting_risk');
            }
            if (period === 3 && ds.governanceRisk > 10) {
                return window.mySimulation.t('hint_governance_risk');
            }
            if (period === 4 && ds.ethicsScore < 15) {
                return window.mySimulation.t('hint_ethics');
            }
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundName', label: 'Round', i18nKey: 'col_round', formatter: function(v) { return self._storedText(v, 'rn_'); } },
                { key: 'results.keyDecision', label: 'Key Decision', i18nKey: 'col_decision', formatter: function(v) { return self._storedText(v, 'kd_'); } },
