        _t(key) {
            var sim = window.mySimulation;
            if (sim && typeof sim.t === 'function') { return sim.t(key); }
            var en = this.getTranslations().en;
            return (en[key] != null) ? en[key] : key;
        }

        // History cells keep the English text calculateResults stores (parts joined by a bar); each part that
        // matches an en value under the given key prefix is shown in the active language, the rest (names, amounts) as is.
        _storedText(v, prefix) {
            var en = this.getTranslations().en;
            var self = this;
            return String(v === undefined || v === null ? '' : v).split(' | ').map(function(part) {
                for (var k in en) {
                    if (k.indexOf(prefix) === 0 && en[k] === part) { return self._t(k); }
                }
                return part;
            }).join(' | ');
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) {
                titleEl.innerHTML = window.mySimulation ? window.mySimulation.t(round.titleKey) : round.titleKey;
            }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = window.mySimulation ? window.mySimulation.t(round.briefingKey) : round.briefingKey;
            }

            var panel = document.getElementById('decisionsPanel');
            if (!panel) return;

            var html = '';
            for (var i = 0; i < round.decisions.length; i++) {
                var dec = round.decisions[i];
                var labelText = window.mySimulation ? window.mySimulation.t(dec.labelKey) : dec.labelKey;
                html += '<div class="estadio-sim-decision-group">';
                html += '<label for="' + dec.id + 'Select">' + labelText + '</label>';
                html += '<select id="' + dec.id + 'Select" class="form-control">';
                for (var j = 0; j < dec.options.length; j++) {
                    var opt = dec.options[j];
                    var optText = window.mySimulation ? window.mySimulation.t(opt.labelKey) : opt.labelKey;
                    html += '<option value="' + opt.value + '">' + optText + '</option>';
                }
                html += '</select>';
                html += '</div>';
            }
            panel.innerHTML = html;

            if (idx === 1 && window.mySimulation && window.mySimulation.state) {
                var ds = window.mySimulation.state.domainState;
                var budgetNote = document.createElement('div');
                budgetNote.style.cssText = 'padding:10px;margin-bottom:12px;border-radius:8px;font-size:0.88rem;';
                if (ds.fonsecaStatus === 'roster') {
                    budgetNote.style.background = 'rgba(231,76,60,0.2)';
                    budgetNote.style.color = '#e74c3c';
                    budgetNote.innerHTML = '⚠ ' + this._t('budget_note_kept');
                } else {
                    budgetNote.style.background = 'rgba(46,204,113,0.2)';
                    budgetNote.style.color = '#2ecc71';
                    budgetNote.innerHTML = '✅ ' + this._t('budget_note_sold').split('{amount}').join(ds.transferBudget.toFixed(1));
                }
                panel.insertBefore(budgetNote, panel.firstChild);
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new EstadioAdapter(), {
            simulationType: 'el_estadio_403',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
